def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 2]), fmt([1, 2, 3]), fmt([-1000000000, 1000000000]), fmt([4, 4, 4, 4]), fmt([0, -1, 0, -1, 0])]
    for n in range(4, 16):
        tests.append(fmt([rng.randint(-100, 100) for _ in range(n)]))
    for _ in range(8):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(rng.randint(16, 30))]))
    for n in (99999, 100000):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt(list(range(1, 100001))))
    tests.append(fmt([10**9] * 100000))
    return tests
